  function wirePhase(ov){var v=$('#kmMotionVideo',ov),play=$('#kmPlay',ov);function apply(ph){KM.phase=ph;$$('[data-phase]',ov).forEach(function(b){b.classList.toggle('active',b.dataset.phase===ph)});if(v){v.pause();try{v.currentTime=phaseTimes(ph)}catch(_){ }play.textContent='▶'}}$$('[data-phase]',ov).forEach(function(b){b.onclick=function(){apply(b.dataset.phase)}});play.onclick=function(){if(!v)return;if(v.paused){v.play().catch(function(){});play.textContent='Ⅱ'}else{v.pause();play.textContent='▶'}};apply('active')}
